/* Assets embedded for the certificate PDF.
 *
 * They live here as base64 rather than as files on disk because the PDF is
 * generated inside a serverless function, where reading project files at
 * runtime is unreliable — the bundler only ships what it can see imported.
 *
 * Fonts: Playfair Display and Poppins, both SIL Open Font License 1.1,
 * subset to Latin plus the Yoruba and naira characters a Nigerian name or
 * amount needs. Regenerate with pyftsubset if the character set has to grow.
 */

export const PLAYFAIR_SEMIBOLD = "";

export const POPPINS_REGULAR = "";

export const POPPINS_MEDIUM = "";

export const RR_LOGO_PNG = "";


export function decodeAsset(b64: string): Uint8Array {
  const bin = typeof Buffer !== "undefined"
    ? Buffer.from(b64, "base64")
    : Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  return new Uint8Array(bin);
}
